def eval_rpn(tokens: list) -> int:
    stack = []
    for token in tokens:
        if token in "+-*/":
            b, a = stack.pop(), stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # division
                # Integer division truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]
```

