def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string not allowed")

    seconds = 0
    i = 0

    while i < len(s):
        if s[i] == 'h':
            if i > 0 and s[i-1].isdigit():
                # Extract hours
                start = i - 1
                while start > 0 and s[start-1].isdigit():
                    start -= 1
                hours = int(s[start:i])
                seconds += hours * 3600
            else:
                raise ValueError(f"Invalid format: {s}")
            i += 1
        elif s[i] == 'm':
            if i > 0 and s[i-1].isdigit():
                start = i - 1
                while start > 0 and s[start-1].isdigit():
                    start -= 1
                minutes = int(s[start:i])
                seconds += minutes * 60
            else:
                raise ValueError(f"Invalid format: {s}")
            i += 1
        elif s[i] == 's':
            if i > 0 and s[i-1].isdigit():
                start = i - 1
                while start > 0 and s[start-1].isdigit():
                    start -= 1
                seconds += int(s[start:i])
            else:
                raise ValueError(f"Invalid format: {s}")
            i += 1
        else:
            if s[i].isdigit():
                i += 1
            else:
                raise ValueError(f"Invalid character: {s[i]}")

    return seconds
