def compress_ranges(nums: list) -> str:
    if not nums:
        return ""

    # Sort and remove duplicates
    sorted_nums = sorted(set(nums))

    # Build ranges
    ranges = []
    i = 0
    while i < len(sorted_nums):
        start = current = sorted_nums[i]
        # Extend the range as long as consecutive numbers are found
        while i + 1 < len(sorted_nums) and sorted_nums[i + 1] == current + 1:
            current = sorted_nums[i + 1]
            i += 1
        # If it's a range of two or more, use hyphen notation
        if current > start:
            ranges.append(f"{start}-{current}")
        else:
            ranges.append(str(start))
        i += 1

    return ",".join(ranges)
```

