def lru_simulate(capacity: int, ops: list) -> list:
    cache = {}
    order = []
    results = []

    for op in ops:
        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                order.remove(key)
            elif len(cache) >= capacity:
                removed_key = order.pop(0)
                del cache[removed_key]
            cache[key] = value
            order.append(key)
        elif op[0] == 'get':
            key = op[1]
            if key in cache:
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results
```

