def format_bytes(n: int) -> str:
    units = ['B', 'KiB', 'MiB', 'GiB']
    unit_values = [1, 1024, 1024**2, 1024**3]

    if n < 1024:
        return f"{n} B"

    for i, value in enumerate(unit_values):
        if n < value * 1024:
            result = n / value
            return f"{result:.1f} {units[i]}"

    return f"{n / unit_values[-1]:.1f} {units[-1]}"
