def next_permutation(nums: list) -> list:
    if not nums:
        return []

    # Find the largest index i such that nums[i] < nums[i+1]
    # If no such index exists, the permutation is the last one
    i = -1
    for j in range(len(nums) - 1):
        if nums[j] < nums[j + 1]:
            i = j

    if i == -1:
        # No next permutation exists, return sorted list
        return sorted(nums)

    # Find the largest index j such that nums[i] < nums[j]
    j = -1
    for k in range(len(nums) - 1, i, -1):
        if nums[i] < nums[k]:
            j = k
            break

    # Swap nums[i] and nums[j]
    nums[i], nums[j] = nums[j], nums[i]

    # Reverse the suffix starting at i+1
    left, right = i + 1, len(nums) - 1
    while left < right:
        nums[left], nums[right] = nums[right], nums[left]
        left += 1
        right -= 1

    return nums
```

